def copy_role_to_capability(apps, schema_editor):
    """Keep each existing account, and turn its single role into one capability."""
    User = apps.get_model('accounts', 'User')
    Grant = apps.get_model('accounts', 'AccountCapability')
    for user in User.objects.all().iterator():
        code = 'service_provider' if user.role == 'worker' else 'customer'
        Grant.objects.get_or_create(user_id=user.pk, code=code)
        if user.active_mode != code:
            user.active_mode = code
            user.save(update_fields=['active_mode'])


def restore_role_from_capability(apps, schema_editor):
    User = apps.get_model('accounts', 'User')
    Grant = apps.get_model('accounts', 'AccountCapability')
    for user in User.objects.all().iterator():
        codes = set(Grant.objects.filter(user_id=user.pk).values_list('code', flat=True))
        user.role = 'worker' if 'service_provider' in codes else 'customer'
        user.save(update_fields=['role'])


